import type { ApiPath, ApiRequest, ApiResponse } from '../types/api';

export interface RetryOptions {
  maxRetries: number;
  backoff: 'linear' | 'exponential';
  baseDelayMs?: number;
}

const sleep = (ms: number) => new Promise((resolve) => setTimeout(resolve, ms));

export async function retryWithBackoff<T>(request: () => Promise<T>, options: RetryOptions): Promise<T> {
  const baseDelayMs = options.baseDelayMs ?? 200;
  let attempt = 0;
  for (;;) {
    try {
      return await request();
    } catch (error) {
      attempt += 1;
      if (attempt > options.maxRetries) throw error;
      const delay = options.backoff === 'exponential' ? baseDelayMs * 2 ** (attempt - 1) : baseDelayMs * attempt;
      await sleep(delay);
    }
  }
}

export type ApiFetchInit<P extends ApiPath> = Omit<RequestInit, 'body'> & {
  /** Typed request body for the route; serialized as JSON. */
  body?: ApiRequest<P>;
};

export async function apiFetch<P extends ApiPath>(path: P, init?: ApiFetchInit<P>): Promise<ApiResponse<P>> {
  return retryWithBackoff(async () => {
    const { body, ...rest } = init ?? {};
    const headers = new Headers(rest.headers);
    if (body !== undefined && !headers.has('Content-Type')) headers.set('Content-Type', 'application/json');
    const response = await fetch(`/api${path}`, {
      ...rest,
      headers,
      body: body === undefined ? undefined : JSON.stringify(body),
    });
    if (!response.ok) throw new Error(`${response.status} ${response.statusText}`);
    return (await response.json()) as ApiResponse<P>;
  }, { maxRetries: 3, backoff: 'exponential' });
}

// Request/response contracts for every route in server/routes.ts.
// Kept standalone (not imported from server/) so the client does not depend on server internals.

export type Role = 'admin' | 'member' | 'viewer';

export interface Subscription {
  id: string;
  userId: string;
  plan: 'starter' | 'team' | 'enterprise';
  status: 'active' | 'past_due' | 'cancelled';
  renewsAt: string;
}

export interface Invoice {
  id: string;
  userId: string;
  amountCents: number;
  issuedAt: string;
  paid: boolean;
}

/** Body returned by every route on 401 / 404 / 429. */
export interface ApiError {
  error: string;
}

// POST /login
export interface LoginRequest {
  email: string;
  password: string;
}
export interface LoginResponse {
  token: string;
}

// GET /me
export type MeRequest = void;
export interface MeResponse {
  id: string;
  role: Role;
}

// GET /subscriptions
export type ListSubscriptionsRequest = void;
export type ListSubscriptionsResponse = Subscription[];

// GET /invoices
export type ListInvoicesRequest = void;
export type ListInvoicesResponse = Invoice[];

// POST /subscriptions/:id/cancel  (the id is a path param; no body)
export type CancelSubscriptionRequest = void;
export type CancelSubscriptionResponse = Subscription;

/** Path -> { request, response } map, keyed by the path passed to apiFetch (without the /api prefix). */
export interface ApiRoutes {
  '/login': { request: LoginRequest; response: LoginResponse };
  '/me': { request: MeRequest; response: MeResponse };
  '/subscriptions': { request: ListSubscriptionsRequest; response: ListSubscriptionsResponse };
  '/invoices': { request: ListInvoicesRequest; response: ListInvoicesResponse };
  [path: `/subscriptions/${string}/cancel`]: { request: CancelSubscriptionRequest; response: CancelSubscriptionResponse };
}

export type ApiPath = keyof ApiRoutes;
export type ApiRequest<P extends ApiPath> = ApiRoutes[P]['request'];
export type ApiResponse<P extends ApiPath> = ApiRoutes[P]['response'];
